<?php
declare(strict_types=1);
require __DIR__.'/../bootstrap.php';require_login();
$u=current_user();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT * FROM short_links WHERE id=? AND user_id=?');$q->execute([$id,(int)$u['id']]);$l=$q->fetch();if(!$l){http_response_code(404);exit('Link not found.');}
$includeBots=($_GET['include_bots']??'0')==='1';$pdo=db();$where='link_id=?';$params=[$id];if(!$includeBots)$where.=' AND is_bot=0';
function stat_group(string $field,int $id,bool $includeBots=false):array{$allow=['referrer','browser','os','device_category','country_code','city','isp','asn'];if(!in_array($field,$allow,true))return[];$label=$field==='referrer'?"COALESCE(NULLIF(referrer,''),'Direct')":($field==='country_code'?"COALESCE(NULLIF(country_code,''),'Unknown')":($field==='city'?"COALESCE(NULLIF(city,''),'Unknown')":$field));$sql="SELECT $label label,COUNT(*) n FROM link_clicks WHERE link_id=?".($includeBots?'':' AND is_bot=0')." GROUP BY 1 ORDER BY n DESC LIMIT 12";$s=db()->prepare($sql);$s->execute([$id]);return $s->fetchAll();}
$count=$pdo->prepare("SELECT COUNT(*) FROM link_clicks WHERE $where");$count->execute($params);$total=(int)$count->fetchColumn();$unique=$pdo->prepare("SELECT COUNT(DISTINCT visitor_hash) FROM link_clicks WHERE $where");$unique->execute($params);$unique=(int)$unique->fetchColumn();$botQ=$pdo->prepare('SELECT COUNT(*) FROM link_clicks WHERE link_id=? AND is_bot=1');$botQ->execute([$id]);$botTotal=(int)$botQ->fetchColumn();
$hours=$pdo->prepare("SELECT HOUR(COALESCE(clicked_at_utc,clicked_at)) h,COUNT(*) n FROM link_clicks WHERE $where GROUP BY HOUR(COALESCE(clicked_at_utc,clicked_at)) ORDER BY h");$hours->execute($params);$hours=$hours->fetchAll();
$days=$pdo->prepare("SELECT DAYOFWEEK(COALESCE(clicked_at_utc,clicked_at)) d,COUNT(*) n FROM link_clicks WHERE $where GROUP BY DAYOFWEEK(COALESCE(clicked_at_utc,clicked_at)) ORDER BY d");$days->execute($params);$days=$days->fetchAll();
$mapQ=$pdo->prepare("SELECT latitude,longitude,country_code,country_name,city,COUNT(*) clicks FROM link_clicks WHERE $where AND latitude IS NOT NULL AND longitude IS NOT NULL GROUP BY latitude,longitude,country_code,country_name,city ORDER BY clicks DESC LIMIT 500");$mapQ->execute($params);$mapPoints=$mapQ->fetchAll();
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="link-'.$l['slug'].'-analytics.csv"');$o=fopen('php://output','w');fputcsv($o,['metric','value']);fputcsv($o,['total_clicks',$total]);fputcsv($o,['unique_visitors',$unique]);fputcsv($o,['bot_clicks',$botTotal]);foreach(['referrer','browser','os','device_category','country_code','city','isp','asn'] as $f){foreach(stat_group($f,$id,$includeBots) as $r)fputcsv($o,[$f.':'.$r['label'],$r['n']]);}fclose($o);exit;}
if(($_GET['export']??'')==='pdf'){require __DIR__.'/../includes/simple-pdf.php';$lines=['PocketCat Link Analytics','Short URL: '.link_public_url($l['slug']),'Destination: '.$l['destination_url'],'Total clicks: '.$total,'Unique visitors: '.$unique,'Bot clicks: '.$botTotal,'','Top referrers'];foreach(stat_group('referrer',$id,$includeBots) as $r)$lines[]=$r['label'].' — '.$r['n'];$lines[]='';$lines[]='Countries';foreach(stat_group('country_code',$id,$includeBots) as $r)$lines[]=$r['label'].' — '.$r['n'];simple_pdf_download('link-'.$l['slug'].'-analytics.pdf',$lines);exit;}
$countryRows=stat_group('country_code',$id,$includeBots);$countryMap=[];foreach($countryRows as $r){if(preg_match('/^[A-Z]{2}$/',(string)$r['label']))$countryMap[$r['label']]=(int)$r['n'];}
require __DIR__.'/../includes/header.php';
?>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin="anonymous">
<div class="page-head analytics-head"><div><span class="eyebrow">ANALYTICS</span><h1><?=e($l['title']?:'Link analytics')?></h1><p><a href="<?=e(link_public_url($l['slug']))?>" target="_blank"><?=e(link_public_url($l['slug']))?></a> → <?=e($l['destination_url'])?></p></div><div class="actions"><a class="btn secondary" href="?id=<?=$id?>&export=csv">CSV</a><a class="btn secondary" href="?id=<?=$id?>&export=pdf">PDF</a></div></div>
<div class="analytics-toolbar card"><label class="analytics-check"><input id="includeBots" type="checkbox" <?=$includeBots?'checked':''?>> <span>Include bot / crawler traffic</span></label><span class="live-badge" id="liveBadge">● Live</span><span class="muted" id="eventStatus">Live polling · updates every 5 seconds</span></div>
<div class="stats"><div class="card stat"><span>Total clicks</span><strong id="totalClicks"><?=$total?></strong></div><div class="card stat"><span>Unique visitors</span><strong><?=$unique?></strong></div><div class="card stat"><span>Bot clicks</span><strong><?=$botTotal?></strong></div><div class="card stat"><span>Status</span><strong style="font-size:18px"><?=e($l['status'])?></strong></div></div>
<div class="grid-main analytics-grid"><?php foreach(['referrer'=>'Referrers','browser'=>'Browsers','os'=>'Operating systems','device_category'=>'Devices','country_code'=>'Countries','city'=>'Cities'] as $f=>$title):?><section class="card"><h2><?=e($title)?></h2><?php $rows=stat_group($f,$id,$includeBots);if(!$rows):?><p class="muted">No data yet.</p><?php else:foreach($rows as $r):?><div class="analytics-row"><span><?=e($r['label'])?></span><strong><?=number_format((int)$r['n'])?></strong></div><?php endforeach;endif;?></section><?php endforeach;?></div>
<section class="card geo-card"><div class="section-head-row"><div><h2>Geo heatmap</h2><p class="muted">Human click intensity from resolved IP geolocation. Pin-level detail is shown in the live event stream.</p></div></div><div id="linkWorldMap" class="link-world-map"></div><?php if(!$mapPoints):?><p class="muted geo-empty">No coordinate data has been resolved yet. The queue worker will enrich new clicks automatically.</p><?php endif;?></section>
<section class="card peak-card"><h2>Peak engagement</h2><p class="muted">Hourly and day-of-week click distribution. Time and quantity are rendered as separate fields.</p><div class="peak-grid"><div><h3>Hour</h3><div class="peak-list"><?php if(!$hours):?><p class="muted">No data yet.</p><?php else:foreach($hours as $r):?><div class="peak-item"><span><?=str_pad((string)$r['h'],2,'0',STR_PAD_LEFT)?>:00</span><strong><?=number_format((int)$r['n'])?></strong></div><?php endforeach;endif;?></div></div><div><h3>Day</h3><div class="peak-list"><?php $names=['','Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];if(!$days):?><p class="muted">No data yet.</p><?php else:foreach($days as $r):?><div class="peak-item"><span><?=e($names[(int)$r['d']]??'Unknown')?></span><strong><?=number_format((int)$r['n'])?></strong></div><?php endforeach;endif;?></div></div></div></section>
<section class="card live-events-card"><div class="section-head-row"><div><span class="eyebrow">LIVE CLICK STREAM</span><h2>Recent events</h2><p class="muted">New events are polled every 5 seconds without opening a long-lived connection.</p></div><span class="event-count" id="eventCount">0 events loaded</span></div><div class="table-wrap live-events-wrap"><table class="live-events-table"><thead><tr><th>Time</th><th>IP</th><th>Source</th><th>Location</th><th>Device</th><th>Browser</th><th>UTM</th><th>Type</th></tr></thead><tbody id="liveEventsBody"><tr><td colspan="8" class="muted">Loading events…</td></tr></tbody></table></div></section>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin="anonymous"></script>
<script>
window.addEventListener('load',function(){
 const linkId=<?=json_encode($id)?>;let lastId=0;const body=document.getElementById('liveEventsBody');const badge=document.getElementById('liveBadge');const status=document.getElementById('eventStatus');const count=document.getElementById('eventCount');const totalEl=document.getElementById('totalClicks');const include=document.getElementById('includeBots');
 const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
 const fmtTime=(x,tz)=>{if(!x)return '—';try{const d=new Date(String(x).replace(' ','T')+'Z');return new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:tz||undefined}).format(d);}catch(e){return x;}};
 function eventRow(r){const ip=r.ip_address||'—';const loc=[r.city,r.region,r.country_code].filter(Boolean).join(', ')||'Unknown';const dev=[r.device_brand,r.device_model,r.device_category].filter(Boolean).join(' · ')||r.device_category||'Unknown';const browser=[r.browser,r.browser_version].filter(Boolean).join(' ');const utm=[r.utm_source,r.utm_medium,r.utm_campaign].filter(Boolean).join(' / ');return `<tr data-event-id="${esc(r.id)}"><td><strong>${esc(fmtTime(r.clicked_at_utc||r.clicked_at,r.timezone_name))}</strong><small>${esc(r.timezone_name||'UTC')}</small></td><td>${esc(ip)}</td><td>${esc(r.referrer||'Direct')}</td><td>${esc(loc)}<small>${r.latitude!==null&&r.longitude!==null?esc(r.latitude+', '+r.longitude):''}</small></td><td>${esc(dev)}</td><td>${esc(browser||'Other')}</td><td>${esc(utm||'—')}</td><td><span class="event-type ${r.is_bot?'is-bot':'is-human'}">${esc(r.is_bot?(r.bot_type||'Bot'):'Human')}</span></td></tr>`;}
 function addRows(rows){if(!rows.length)return;rows.forEach(r=>{if(body.querySelector(`tr[data-event-id="${r.id}"]`))return;body.insertAdjacentHTML('afterbegin',eventRow(r));if(Number(r.id)>lastId)lastId=Number(r.id);addMarker(r);});const all=body.querySelectorAll('tr[data-event-id]');if(all.length>100){for(let i=100;i<all.length;i++)all[i].remove();}count.textContent=body.querySelectorAll('tr[data-event-id]').length+' events loaded';}
 const map=L.map('linkWorldMap',{worldCopyJump:true,scrollWheelZoom:true,zoomControl:true}).setView([20,0],2);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const markers=L.layerGroup().addTo(map);
 const markerSeen=new Set();
 function addMarker(p){const lat=Number(p.latitude),lon=Number(p.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))return;const key=String(p.id||'')+':'+lat+':'+lon;if(markerSeen.has(key))return;markerSeen.add(key);const title=[p.city,p.country_name||p.country_code].filter(Boolean).join(', ')||'Unknown location';const time=esc(fmtTime(p.clicked_at_utc||p.clicked_at,p.timezone_name));L.marker([lat,lon]).bindPopup(`<strong>${esc(title)}</strong><br>IP: ${esc(p.ip_address||'—')}<br>Time: ${time}<br>Device: ${esc(p.device_category||'—')}<br>Browser: ${esc(p.browser||'—')}`).addTo(markers);}
 const initial=<?=json_encode($mapPoints)?>;initial.forEach(p=>{const lat=Number(p.latitude),lon=Number(p.longitude);if(Number.isFinite(lat)&&Number.isFinite(lon)){L.circleMarker([lat,lon],{radius:Math.min(18,5+Number(p.clicks)),weight:1}).bindPopup(`<strong>${esc(p.city||p.country_name||p.country_code||'Unknown')}</strong><br>${esc(p.clicks)} clicks`).addTo(markers);}});if(initial.length){const bounds=[];initial.forEach(p=>{if(p.latitude!==null&&p.longitude!==null)bounds.push([Number(p.latitude),Number(p.longitude)]);});if(bounds.length)map.fitBounds(bounds,{padding:[25,25],maxZoom:5});}
 async function initialLoad(){try{const url=`/api/link-events/?id=${linkId}&include_bots=${include.checked?'1':'0'}&since=0`;const res=await fetch(url,{credentials:'same-origin',cache:'no-store'});const json=await res.json();if(!res.ok)throw new Error(json.error||'Request failed');const rows=(json.data||[]).slice().reverse();body.innerHTML='';addRows(rows);if(json.latest_id)lastId=Number(json.latest_id);status.textContent='Live polling ready';badge.textContent='● Live';badge.classList.remove('offline');}catch(e){badge.textContent='● Offline';badge.classList.add('offline');status.textContent=e.message||'Live stream unavailable';}}
 let pollTimer=null;let polling=false;
 async function pollEvents(){if(polling)return;polling=true;try{const url=`/api/link-events/?id=${linkId}&include_bots=${include.checked?'1':'0'}&since=${lastId}`;const res=await fetch(url,{credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}});const json=await res.json();if(!res.ok)throw new Error(json.error||'Request failed');const rows=(json.data||[]).slice().reverse();if(rows.length){const human=rows.filter(r=>!Number(r.is_bot)).length;addRows(rows);totalEl.textContent=String(Number(totalEl.textContent||0)+human);status.textContent='Updated '+new Date().toLocaleTimeString();}else{status.textContent='Live polling · checked '+new Date().toLocaleTimeString();}badge.textContent='● Live';badge.classList.remove('offline');}catch(e){badge.textContent='● Offline';badge.classList.add('offline');status.textContent='Live polling unavailable — will retry automatically';}finally{polling=false;if(!document.hidden){pollTimer=setTimeout(pollEvents,5000);}}}
 function startPolling(){if(pollTimer)clearTimeout(pollTimer);pollTimer=null;pollEvents();}
 include.addEventListener('change',()=>{lastId=0;body.innerHTML='';markerSeen.clear();initialLoad().then(startPolling);});document.addEventListener('visibilitychange',()=>{if(!document.hidden)startPolling();});initialLoad().then(startPolling);
});
</script>
<?php require __DIR__.'/../includes/footer.php'; ?>
